prompt --application/pages/page_00002
begin
wwv_flow_imp_page.create_page(
 p_id=>2
,p_name=>'WebSockets'
,p_alias=>'REQUESTS'
,p_step_title=>'Requests - WebSockets'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Display the new data warning',
'function newDataWebSocket(){',
'    div = $(''.c-2'')',
'    if (div.hasClass(''c-hide-bt-refresh'')){',
'        div.toggleClass(''c-hide-bt-refresh'');',
'    }',
'}',
'',
'// WebSocket connection and events',
'let ws = new WebSocket("ws://127.0.0.1:8080");',
'',
'ws.addEventListener(''open'', () => {',
'    console.log(''WebSocket connected.'');',
'});',
'',
'ws.addEventListener(''message'', event => {',
'    console.log(''Message from server:'', event.data);',
'    newDataWebSocket();',
'});'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Status */',
'.c-status-draft{',
'    background: #87818b;',
'}',
'.c-status-opened{',
'    background: rgb(28, 103, 165);',
'}',
'.c-status-closed{',
'    background: rgb(56, 107, 33);',
'}',
'.c-width-status{',
'    display: inline-block;',
'    width: 3.5rem;',
'    padding: 2px;',
'    border-radius: 0.25rem;',
'    color: white;',
'    font-weight: bold;',
'}',
'/* Requests */',
'.c-req{',
'    display: inline-block;',
'    padding: 2px;',
