,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Display new data warning',
'function newData(prPriority){',
'    div = $(''.c-2'')',
'    if (div.hasClass(''c-hide-bt-refresh'')){',
'        div.toggleClass(''c-hide-bt-refresh'');',
'        if (prPriority == ''Normal''){',
'           div.removeClass(''c-priority-high'').addClass(''c-priority-normal'');',
'        } else {',
'           div.removeClass(''c-priority-normal'').addClass(''c-priority-high'');',
'        }             ',
'    }',
'}',
'',
'//const socket = io("http://000.000.0.00:3000");',
'const socket = io("https://your-server-socket.com"); // public domain to fix the mixed content problem',
'',
'socket.on("connect", function () {',
'    console.log("socket connection ID " + socket.id);',
'});',
'',
'socket.on("new-req-normal", function (data) {',
'    newData(''Normal'');',
'});',
'',
'socket.on("new-req-high", function (data) {',
'    newData(''High'');',
'});'))
